import type { Request, Response } from 'express';

export interface Product {
  id: string;
  name: string;
  category: 'pottery' | 'textiles' | 'woodwork' | 'jewelry';
  price: number;
  description: string;
  imageSlot: string;
  featured: boolean;
}

const products: Product[] = [
  // Pottery
  {
    id: 'p1',
    name: 'Terracotta Serving Bowl',
    category: 'pottery',
    price: 68,
    description: 'Hand-thrown from local clay, this generous serving bowl features a warm terracotta glaze with subtle texture marks from the potter\'s hands.',
    imageSlot: '/airo-assets/images/products/pottery-bowl',
    featured: true,
  },
  {
    id: 'p2',
    name: 'Stoneware Coffee Mug',
    category: 'pottery',
    price: 38,
    description: 'A perfectly weighted mug with a comfortable thumb rest and a rich earthy glaze. Holds 12oz and feels wonderful in your hands on a slow morning.',
    imageSlot: '/airo-assets/images/products/pottery-mug',
    featured: false,
  },
  {
    id: 'p3',
    name: 'Ceramic Bud Vase',
    category: 'pottery',
    price: 52,
    description: 'Slender and elegant, this bud vase is wheel-thrown and finished with a matte ash glaze. Perfect for a single stem or small wildflower bouquet.',
    imageSlot: '/airo-assets/images/products/pottery-vase',
    featured: false,
  },
  // Textiles
  {
    id: 't1',
    name: 'Handwoven Wool Throw',
    category: 'textiles',
    price: 145,
    description: 'Woven on a floor loom using undyed natural wool, this throw is soft, warm, and gets better with every wash. A true heirloom piece.',
    imageSlot: '/airo-assets/images/products/textiles-throw',
    featured: true,
  },
  {
    id: 't2',
    name: 'Market Basket',
    category: 'textiles',
    price: 72,
    description: 'Tightly woven from sustainably harvested rattan, this market basket is sturdy enough for groceries and beautiful enough for your living room.',
    imageSlot: '/airo-assets/images/products/textiles-basket',
    featured: false,
  },
  {
    id: 't3',
    name: 'Embroidered Linen Cushion',
    category: 'textiles',
    price: 89,
    description: 'Hand-embroidered botanical motifs on natural linen. Each cushion takes over 8 hours to complete and is filled with organic buckwheat.',
    imageSlot: '/airo-assets/images/products/textiles-cushion',
    featured: false,
  },
  // Woodwork
  {
    id: 'w1',
    name: 'Turned Walnut Bowl',
    category: 'woodwork',
    price: 118,
    description: 'Lathe-turned from a single piece of black walnut, this bowl showcases the natural grain and warmth of the wood. Finished with food-safe oil.',
    imageSlot: '/airo-assets/images/products/woodwork-bowl',
    featured: true,
  },
  {
    id: 'w2',
    name: 'Floating Wall Shelf',
    category: 'woodwork',
    price: 95,
    description: 'Crafted from reclaimed white oak with hand-cut dovetail joints. Each shelf is unique, bearing the character marks of its previous life.',
    imageSlot: '/airo-assets/images/products/woodwork-shelf',
    featured: false,
  },
  {
    id: 'w3',
    name: 'End-Grain Cutting Board',
    category: 'woodwork',
    price: 84,
    description: 'A mosaic of maple, walnut, and cherry end-grain blocks, glued and finished to create a self-healing cutting surface that\'s as beautiful as it is functional.',
    imageSlot: '/airo-assets/images/products/woodwork-cutting-board',
    featured: false,
  },
  // Jewelry
  {
    id: 'j1',
    name: 'Sterling Silver Ring',
    category: 'jewelry',
    price: 78,
    description: 'Hand-forged from sterling silver with a hammered texture that catches the light beautifully. Available in sizes 5–10.',
    imageSlot: '/airo-assets/images/products/jewelry-ring',
    featured: true,
  },
  {
    id: 'j2',
    name: 'Stone Pendant Necklace',
    category: 'jewelry',
    price: 96,
    description: 'A raw labradorite stone wrapped in fine silver wire and hung on a delicate 18" chain. No two stones are alike.',
    imageSlot: '/airo-assets/images/products/jewelry-necklace',
    featured: false,
  },
  {
    id: 'j3',
    name: 'Hammered Gold Earrings',
    category: 'jewelry',
    price: 112,
    description: 'Hand-hammered 14k gold-fill hoops with a warm, organic texture. Lightweight and comfortable for all-day wear.',
    imageSlot: '/airo-assets/images/products/jewelry-earrings',
    featured: false,
  },
];

export default function handler(req: Request, res: Response) {
  const { category, featured } = req.query;

  let result = [...products];

  if (category && typeof category === 'string') {
    result = result.filter((p) => p.category === category.toLowerCase());
  }

  if (featured === 'true') {
    result = result.filter((p) => p.featured);
  }

  res.json(result);
}

