/**
 * Products API service module
 *
 * All data fetching for products goes through this module.
 * Components and route loaders import from here — never fetch /api/products directly.
 */

export interface Product {
  id: string;
  name: string;
  category: 'pottery' | 'textiles' | 'woodwork' | 'jewelry';
  price: number;
  description: string;
  imageSlot: string;
  featured: boolean;
}

export interface ProductsQuery {
  category?: Product['category'];
  featured?: boolean;
}

async function fetchProducts(query: ProductsQuery = {}): Promise<Product[]> {
  const params = new URLSearchParams();
  if (query.category) params.set('category', query.category);
  if (query.featured) params.set('featured', 'true');

  const url = `/api/products${params.size > 0 ? `?${params}` : ''}`;
  const res = await fetch(url);

  if (!res.ok) {
    throw new Response(null, { status: res.status });
  }

  return res.json() as Promise<Product[]>;
}

export const productsApi = {
  /** Fetch all products, optionally filtered by category */
  getAll: (query?: ProductsQuery) => fetchProducts(query),

  /** Fetch only featured products */
  getFeatured: () => fetchProducts({ featured: true }),

  /** Fetch products in a specific category */
  getByCategory: (category: Product['category']) => fetchProducts({ category }),
};

